.section/pm seg_pmco;

/* One cued strip. In: r1 = its post-fader pool slot, r2 = its pre-fader
 * tap slot, r3 = strip index 0..31. Clobbers r0, r4-r8, i0-i3. */
.global _cue_strip;
_cue_strip:
    l0 = 0; l1 = 0; l2 = 0; l3 = 0;
    r4 = dm(_cue_n);
    r4 = r4 + 1;
    dm(_cue_n) = r4;
    i1 = _cue_fl;
    i2 = _cue_fr;
    r6 = -28;
    r4 = dm(_cue_mode);
    r4 = pass r4;
    if ne jump (pc, .cue_afl);
    i0 = r2;                          /* PFL: pre-fader, mono, unity to both */
    lcntr = DSP4_BLOCK_SIZE, do .cue_pfl until lce;
        r0 = dm(i0, 1);
        f0 = float r0 by r6;
        f4 = dm(0, i1);
        f4 = f4 + f0;
        dm(i1, 1) = f4;
        f5 = dm(0, i2);
        f5 = f5 + f0;
.cue_pfl:
        dm(i2, 1) = f5;
    rts;
.cue_afl:
    r4 = _cue_legs;                   /* AFL / SIP: post-fader x pan legs */
    r5 = r3 + r3;
    r4 = r4 + r5;
    i3 = r4;
    r7 = dm(0, i3);
    r8 = dm(1, i3);
    i3 = r7;
    r7 = dm(0, i3);
    i3 = r8;
    r8 = dm(0, i3);
    f7 = float r7 by r6;
    f8 = float r8 by r6;
    i0 = r1;
    lcntr = DSP4_BLOCK_SIZE, do .cue_afl_lp until lce;
        r0 = dm(i0, 1);
        f0 = float r0 by r6;
        f4 = f0 * f7;
        f5 = dm(0, i1);
        f5 = f5 + f4;
        dm(i1, 1) = f5;
        f4 = f0 * f8;
        f5 = dm(0, i2);
        f5 = f5 + f4;
.cue_afl_lp:
        dm(i2, 1) = f5;
    rts;
_cue_strip.end:

/* Once per block, after the whole chain. Clobbers r0-r9, i0-i5. */
.global _cue_finish;
_cue_finish:
    l0 = 0; l1 = 0; l2 = 0; l3 = 0; l4 = 0; l5 = 0;
    r6 = -28;
    r9 = 0;
    i3 = _cue_bus_sel;
    i4 = _cue_bus_blk;
    lcntr = 17, do .cue_bus until lce;
        r0 = dm(i3, 1);
        r1 = dm(i4, 1);
        r2 = dm(i4, 1);
        r0 = pass r0;
        if eq jump (pc, .cue_bus);
        r9 = r9 + 1;
        i0 = r1;
        i5 = r2;
        i1 = _cue_fl;
        i2 = _cue_fr;
        lcntr = DSP4_BLOCK_SIZE, do .cue_bus_lp until lce;
            r7 = dm(i0, 1);
            f7 = float r7 by r6;
            f4 = dm(0, i1);
            f4 = f4 + f7;
            dm(i1, 1) = f4;
            r8 = dm(i5, 1);
            f8 = float r8 by r6;
            f5 = dm(0, i2);
            f5 = f5 + f8;
.cue_bus_lp:
            dm(i2, 1) = f5;
.cue_bus:
        nop;
    r0 = dm(_cue_n);
    r0 = r0 + r9;
    dm(_cue_active) = r0;
    r0 = pass r0;
    if ne jump (pc, .cue_sum);
    r0 = dm(_cue_src);                /* NOTHING CUED: the assigned source */
    r1 = 0;
    r2 = 16;
    comp(r0, r2);
    if gt r0 = r1;
    comp(r0, r1);
    if lt r0 = r1;
    r0 = r0 + r0;
    r1 = _cue_bus_blk;
    r1 = r1 + r0;
    i3 = r1;
    r1 = dm(0, i3);
    r2 = dm(1, i3);
    i0 = r1;
    i5 = r2;
    i1 = _buf_C1_CUE_L;
    i2 = _buf_C1_CUE_R;
    lcntr = DSP4_BLOCK_SIZE, do .cue_cp until lce;
        r0 = dm(i0, 1);
        dm(i1, 1) = r0;
        r0 = dm(i5, 1);
.cue_cp:
        dm(i2, 1) = r0;
    rts;
.cue_sum:
    i0 = _cue_fl;
    i5 = _cue_fr;
    i1 = _buf_C1_CUE_L;
    i2 = _buf_C1_CUE_R;
    r6 = 28;
    r5 = 0;
    lcntr = DSP4_BLOCK_SIZE, do .cue_fix until lce;
        f0 = dm(0, i0);
        r0 = fix f0 by r6;            /* saturating on overflow */
        dm(i0, 1) = r5;               /* the sum restarts at +0.0 */
        dm(i1, 1) = r0;
        f0 = dm(0, i5);
        r0 = fix f0 by r6;
        dm(i5, 1) = r5;
.cue_fix:
        dm(i2, 1) = r0;
    r0 = 0;
    dm(_cue_n) = r0;
    rts;
_cue_finish.end:

/* The parameter link's out-of-table branch (chip1/spi_handler.asm).
 * Read. In: r2 = SPI address. Out: r4 = the word (0 if unmapped).
 * Clobbers r4, r5, i0, m0 -- the diag handlers' set. */
.global _cue_spi_read;
_cue_spi_read:
    r5 = CUE_SPI_BASE;
    r4 = r2 - r5;
    r5 = 0;
    comp(r4, r5);
    if lt jump (pc, .cue_rd_zero);
    r5 = CUE_SPI_N;
    comp(r4, r5);
    if ge jump (pc, .cue_rd_zero);
    i0 = _cue_spi_ptr;
    m0 = r4;
    modify(i0, m0);
    r5 = dm(0, i0);
    r5 = pass r5;
    if eq jump (pc, .cue_rd_zero);
    i0 = r5;
    r4 = dm(0, i0);
    rts;
.cue_rd_zero:
    r4 = 0;
    rts;
_cue_spi_read.end:

/* Write. In: r2 = SPI address, r1 = value. Out: r4 = 0 taken, 1 refused
 * (out of the block, unmapped or read-only). Clobbers r4, r5, i0, m0. */
.global _cue_spi_write;
_cue_spi_write:
    r5 = CUE_SPI_BASE;
    r4 = r2 - r5;
    r5 = 0;
    comp(r4, r5);
    if lt jump (pc, .cue_wr_no);
    r5 = CUE_SPI_N;
    comp(r4, r5);
    if ge jump (pc, .cue_wr_no);
    i0 = _cue_spi_wr;
    m0 = r4;
    modify(i0, m0);
    r5 = dm(0, i0);
    r5 = pass r5;
    if eq jump (pc, .cue_wr_no);
    i0 = _cue_spi_ptr;
    m0 = r4;
    modify(i0, m0);
    r5 = dm(0, i0);
    i0 = r5;
    dm(0, i0) = r1;
    r4 = 0;
    rts;
.cue_wr_no:
    r4 = 1;
    rts;
_cue_spi_write.end:

#endif /* DSP4_CUE && DSP4_BLOCK_KERNELS && CHIP_ID == 1 */
